"""Local-only fault controls and evidence for the sample result publication lab."""
import secrets

DEMO_TOKEN = secrets.token_hex(24)

HTML = '''<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>Correction Safety Lab · CN Project</title>
<style>@font-face{font-family:Poppins;src:url('/poppins-400.ttf')}@font-face{font-family:Poppins;src:url('/poppins-500.ttf');font-weight:500}
*{box-sizing:border-box}body{margin:0;padding:28px 18px;background:#eff4fa;color:#26364a;font:13px Poppins,sans-serif}
main{max-width:1000px;margin:auto}.header{display:flex;align-items:center;gap:16px;margin-bottom:24px}.header img{width:62px;height:62px;border-radius:50%}h1{font-size:24px;font-weight:500;color:blue;margin:0 0 5px}p{line-height:1.8;margin:5px 0}.header a{margin-left:auto;color:#007bff;text-decoration:none;white-space:nowrap}.notice{background:#fff5df;border:1px solid #ffe1a6;padding:14px 18px;border-radius:6px;font-size:11px;margin-bottom:20px}.grid{display:grid;grid-template-columns:1.2fr 1fr;gap:20px}.card{background:white;border:1px solid #dce5ef;border-radius:8px;padding:24px;min-width:0}h2{font-size:16px;font-weight:500;margin:0 0 16px;color:#163358}.label{font-size:10px;letter-spacing:.8px;text-transform:uppercase;color:#6a7b8e}.value{font-size:28px;font-weight:500;color:#007bff;margin:5px 0}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:18px}.small{font-size:11px;color:#697b8e}.actions{display:flex;gap:10px;flex-wrap:wrap;margin:14px 0}button,.link-btn{border:1px solid #c5d7ed;padding:10px 13px;border-radius:4px;background:#edf5ff;color:#005ec3;font:12px Poppins,sans-serif;cursor:pointer;text-decoration:none;display:inline-block}.primary{background:#007bff;color:white;border-color:#007bff}button:disabled{opacity:.5;cursor:wait}button:focus-visible,a:focus-visible{outline:3px solid orange;outline-offset:3px}.step{padding:12px 0;border-bottom:1px solid #edf1f5}.step strong{color:#163358;font-weight:500}code{font-size:12px;color:#005ec3}.alert{min-height:28px;line-height:1.6;color:#005ec3}#error{color:#b52626}.events{max-height:350px;overflow:auto;border-top:1px solid #dce5ef;margin-top:15px}table{border-collapse:collapse;width:100%;font-size:10px}td,th{text-align:left;padding:10px 6px;border-bottom:1px solid #edf1f5;vertical-align:top}th{font-weight:500;color:#697b8e}.counter{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #edf1f5}.pill{font-size:10px;background:#eff6ff;border:1px solid #bfd5ef;padding:5px 8px;border-radius:4px;display:inline-block}.footer{font-size:10px;color:#697b8e;margin-top:20px}@media(max-width:740px){.grid{grid-template-columns:1fr}.header{flex-wrap:wrap}.header a{margin-left:0}.card{padding:20px}h1{font-size:20px}.metrics{gap:8px}.value{font-size:25px}}</style></head><body><main>
<div class="header"><img src="/mepco_crest.png" alt="College crest"><div><h1>Correction Safety Lab</h1><p class="small">Mepco Schlenk · Computer Networks demonstration</p></div><a href="/">← Results portal</a></div>
<div class="notice">Local sample records only. These controls do not connect to the college database. The check establishes the current version at a verification decision; a later correction can create a newer version.</div>
<div class="grid"><section class="card"><h2>One student. Two published results.</h2><p class="small">24BAD025 · Computer Networks</p><div class="metrics"><div><div class="label">Published mark</div><div class="value" id="mark">—</div></div><div><div class="label">Version</div><div class="value" id="version">—</div></div><div><div class="label">Result</div><div class="value" id="classification">—</div></div></div><span id="authority" class="pill">Loading publication status…</span>
<div class="step"><strong>1. Prepare the older result</strong><p class="small">Publish 38 marks and seed the portal cache with this FAIL result.</p><div class="actions"><button onclick="act('prepare')">Prepare 38 marks</button></div></div>
<div class="step"><strong>2. Publish a correction</strong><p class="small">Publish 43 marks. Keep the older cache entry so the freshness gate can reject it.</p><div class="actions"><button class="primary" onclick="act('correct')">Publish correction: 43</button><a class="link-btn" href="/result?roll=24BAD025" target="_blank" rel="noopener">View current marksheet →</a></div></div>
<div class="step"><strong>3. Test the TCP version protocol</strong><p class="small">Deliberately send a previous version with a valid CRC. The client should send STALE_NACK and recover on the same admitted connection.</p><div class="actions"><button onclick="act('stale')">Send old reply once</button><button class="primary" onclick="testTcp()" id="testBtn">Test TCP delivery</button></div></div>
<div class="step"><strong>Optional: test while students are queued</strong><p class="small">Enable slow mode, send a 50-student burst, and open the student portal in another tab. Publish the correction while the student is waiting.</p><div class="actions"><button onclick="traffic('slowmo')">Slow mode · W=3</button><button onclick="traffic('burst')">50-student burst</button><button onclick="traffic('normal')">Restore normal mode</button></div><p id="trafficStatus" class="small"></p></div><div class="step"><strong>4. Test safe failure handling</strong><p class="small">A TCP failure can use a verified current snapshot. When the publication authority is paused, old cached marksheets must be blocked.</p><div class="actions"><button onclick="act('fail')">Fail next TCP delivery</button><button onclick="act('toggle_authority')" id="authorityBtn">Pause verification</button></div></div><p id="message" class="alert" role="status"></p><p id="error" class="alert" role="alert"></p><p id="testResult" class="small" aria-live="polite"></p></section>
<section class="card"><h2>Observed evidence</h2><div id="counters"></div><h2 style="margin-top:24px">Recent protocol events</h2><p class="small">Counts represent this running process, not a production guarantee.</p><div class="events"><table><thead><tr><th>Event</th><th>Evidence</th></tr></thead><tbody id="events"></tbody></table></div></section></div><p class="footer">SHA-256 checks snapshot consistency. CRC-32 checks transmission integrity. Neither authenticates a college publication. Production use needs trusted publication access and authenticated administration.</p></main>
<script>
const demoToken='__TOKEN__';
async function refresh(){try{const r=await fetch('/api/demo/status');const d=await r.json();if(!r.ok)throw Error(d.error||'Status unavailable');document.getElementById('mark').textContent=d.current?d.current.scores['Computer Networks']:'—';document.getElementById('version').textContent=d.current?'v'+d.current.result_version:'—';document.getElementById('classification').textContent=d.current?d.current.status:'—';document.getElementById('authority').textContent=d.available?'Publication verification available':'Verification paused · deliveries blocked';document.getElementById('authorityBtn').textContent=d.available?'Pause verification':'Restore verification';const labels={stale_nacks:'Outdated TCP replies rejected',crc_nacks:'CRC retransmissions requested',version_acks:'TCP versions confirmed',cache_rejections:'Old/inconsistent cache entries rejected',safe_fallbacks:'Current snapshots used',unverified_blocked:'Unverified deliveries blocked',publications:'Sample publications'};const counters=document.getElementById('counters');counters.replaceChildren();Object.entries(labels).forEach(([k,v])=>{const row=document.createElement('div');row.className='counter';const label=document.createElement('span');label.textContent=v;const count=document.createElement('strong');count.textContent=d.counters[k];row.append(label,count);counters.append(row)});const events=document.getElementById('events');events.replaceChildren();d.events.slice().reverse().slice(0,16).forEach(e=>{const row=document.createElement('tr');const name=document.createElement('td');name.textContent=e.event;const info=document.createElement('td');info.textContent=JSON.stringify(Object.fromEntries(Object.entries(e).filter(([k])=>k!=='time'&&k!=='event')));row.append(name,info);events.append(row)})}catch(e){document.getElementById('error').textContent=e.message}}
async function act(action){document.getElementById('error').textContent='';try{const r=await fetch('/api/demo/action',{method:'POST',headers:{'Content-Type':'application/json','X-Demo-Token':demoToken},body:JSON.stringify({action})});const d=await r.json();if(!r.ok)throw Error(d.error||'Action failed');document.getElementById('message').textContent=d.message;await refresh()}catch(e){document.getElementById('error').textContent=e.message}}
async function traffic(mode){try{const url=mode==='burst'?'/api/simulate_burst?count=50':'/api/set_mode?mode='+mode;const r=await fetch(url,{headers:{'X-Demo-Token':demoToken}});const d=await r.json();if(!r.ok)throw Error(d.error||'Traffic control failed');document.getElementById('trafficStatus').textContent=mode==='burst'?'50 sample requests sent. Open the student portal and submit a result.':mode==='slowmo'?'Slow mode enabled: 3 slots, 1.2-second processing delay.':'Normal mode restored: 10 slots, 0.2-second processing delay.'}catch(e){document.getElementById('error').textContent=e.message}}
async function testTcp(){const btn=document.getElementById('testBtn');btn.disabled=true;document.getElementById('testResult').textContent='Checking framed TCP result…';try{const r=await fetch('/api/query?roll=24BAD025&force=1');const d=await r.json();document.getElementById('testResult').textContent=d.success?'Delivered v'+d.release_version+' · '+d.result_data.scores['Computer Networks']+' marks · '+d.result_data.status+' · stale retries: '+(d.stale_retries||0)+' · source: '+d.delivery_source:'Delivery blocked: '+d.status_message;await refresh()}catch(e){document.getElementById('error').textContent=e.message}finally{btn.disabled=false}}
refresh();setInterval(refresh,1500);
</script></body></html>'''


def page():
    return HTML.replace("__TOKEN__", DEMO_TOKEN)
